namespace Zjcs.Official.PartnersUI
{
using Object = UnityEngine.Object;
using Zjcs.Official.ProfessionUI;
using System;
using System.Collections.Generic;
using UnityEngine;

[ExecuteAlways]
public class AppearanceUILiteSeparator : MonoBehaviour
{
    [Serializable]
    public class SeparatorSlotFollow
    {
        public string SlotName;

        public bool IsFront;

        public Transform Transform;

        public IProfessionSkinClipSlot Slot;

        [NonSerialized]
        public int DrawOrder;

        public void SetParent(List<Transform> list, int index)
        {
            if (!((Object)(object)Transform == (Object)null))
            {
                int num = (IsFront ? index : (index - 1));
                if (num < 0)
                {
                    num = 0;
                }
                Transform.SetParent(list[num]);
            }
        }
    }

    [SerializeField]
    private Component mSkeletonGraphic;

    private IProfessionAppearancePartGraphic Graphic => (IProfessionAppearancePartGraphic)mSkeletonGraphic;

    [SerializeField]
    private List<SeparatorSlotFollow> mFollowList;

    private void OnEnable()
    {
        if ((Object)(object)mSkeletonGraphic == (Object)null)
        {
            mSkeletonGraphic = (Component)GetComponent<IProfessionAppearancePartGraphic>();
        }
        InitSlots();
    }

    private void Update()
    {





        if (mFollowList == null)
        {
            return;
        }
        IProfessionSkinClipSlot[] items = Graphic.Skeleton.DrawOrder;
        int i = 0;
        for (int count = Graphic.separatorPartInstructions.Count; i < count; i++)
        {
            ProfessionAppearancePartInstruction val = Graphic.separatorPartInstructions[i];
            int j = 0;
            for (int count2 = mFollowList.Count; j < count2; j++)
            {
                SeparatorSlotFollow separatorSlotFollow = mFollowList[j];
                IProfessionSkinClipSlot val2 = items[val.endSlot];
                if (separatorSlotFollow.Slot == val2 && separatorSlotFollow.DrawOrder != val.endSlot)
                {
                    separatorSlotFollow.DrawOrder = val.endSlot;
                    separatorSlotFollow.SetParent(Graphic.SeparatorParts, i);
                }
            }
        }
    }

    private void InitSlots()
    {
        if (mFollowList == null)
        {
            return;
        }
        IProfessionAppearancePartSkeleton skeleton = Graphic.Skeleton;
        foreach (SeparatorSlotFollow mFollow in mFollowList)
        {
            mFollow.Slot = skeleton.FindSlot(mFollow.SlotName);
        }
    }
}

}
